import{_ as p,K as i,a as l,c as n,ac as e,q as t,b as o,k as s}from"./chunks/framework.BSuaGltH.js";const I=JSON.parse('{"title":"gRPC调用、失败与演进契约","description":"RPC形状、截止预算、状态码、重试、流控、认证授权和兼容升级。","frontmatter":{"title":"gRPC调用、失败与演进契约","description":"RPC形状、截止预算、状态码、重试、流控、认证授权和兼容升级。","showdocs":{"topics":[{"id":"grpc","title":"RPC 与 gRPC","link":"/topics/grpc/"}],"kind":"调用与生命周期","scope":"general","audience":"general","group":"原理与设计","seriesTitle":"gRPC调用契约：模型与推演","summary":"RPC形状、截止预算、状态码、重试、流控、认证授权和兼容升级。","status":"active","related":[{"title":"图书查询RPC协议练习","link":"/principles/protocols/grpc/application","kind":"协议与完整应用","scope":"general","audience":"general"}],"prev":false,"next":{"text":"图书查询RPC协议练习","link":"/principles/protocols/grpc/application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"图书查询RPC协议练习","link":"/principles/protocols/grpc/application"}},"headers":[],"relativePath":"principles/protocols/grpc/rpc-contracts.md","filePath":"principles/protocols/grpc/rpc-contracts.md"}'),c={name:"principles/protocols/grpc/rpc-contracts.md"};function h(d,a,u,g,f,k){const r=i("Mermaid");return l(),n("div",null,[a[0]||(a[0]=e('<h1 id="grpc调用、失败与演进契约" tabindex="-1">gRPC调用、失败与演进契约 <a class="header-anchor" href="#grpc调用、失败与演进契约" aria-label="Permalink to &quot;gRPC调用、失败与演进契约&quot;">​</a></h1><h2 id="part-1" tabindex="-1">RPC调用模型与截止时间 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;RPC调用模型与截止时间 {#part-1}&quot;">​</a></h2><p><span id="part-1-grpc调用契约-问题、表示与约束"></span></p><p>前置：理解客户端/服务端、请求响应、流式返回与期限；本机示例使用 Python 3.10+，依赖版本见下文。教学范围为proto3；Python3.10+；grpcio/grpcio-tools1.76.0；protobuf6.33.0。核对日期2026-10-17。示例未执行，本轮没有安装依赖、生成协议代码、启动服务或浏览器预览。完整文件与输入见<a href="/principles/protocols/grpc/application">图书查询协议、服务端与客户端示例</a>；推演结论只适用于写明的模型。</p><h3 id="part-1-rpc" tabindex="-1">gRPC与本地调用差异 <a class="header-anchor" href="#part-1-rpc" aria-label="Permalink to &quot;gRPC与本地调用差异 {#part-1-rpc}&quot;">​</a></h3><p>gRPC与本地调用差异在于远程交互会延迟、失败和产生不确定结果。生成的客户端桩让调用形式相似，却不能抹去连接、序列化与截止时间。服务定义列出方法和消息，业务方仍须定义认证、幂等和错误语义。</p><h3 id="part-1-shapes" tabindex="-1">四类RPC消息形状 <a class="header-anchor" href="#part-1-shapes" aria-label="Permalink to &quot;四类RPC消息形状 {#part-1-shapes}&quot;">​</a></h3><p>四类RPC消息形状包含单次请求单次响应、服务端流、客户端流和双向流式。流内部有序不等于多个调用之间全局有序，两个方向独立推进也不保证业务关联自动匹配。选流式前先确定背压、结束条件与断线后的续读位置。</p><h3 id="part-1-deadline" tabindex="-1">截止时间如何传递 <a class="header-anchor" href="#part-1-deadline" aria-label="Permalink to &quot;截止时间如何传递 {#part-1-deadline}&quot;">​</a></h3><p>截止时间如何传递需要计算剩余预算，不能每个下游再给一份完整超时。客户端超时可能发生在服务端已完成之后；服务端应感知取消并停止不必要工作，但已提交的副作用不会自动撤销。本文只读官方语义，没有执行RPC。</p><h3 id="part-1-调用链共享同一截止预算" tabindex="-1">调用链共享同一截止预算 <a class="header-anchor" href="#part-1-调用链共享同一截止预算" aria-label="Permalink to &quot;调用链共享同一截止预算 {#part-1-调用链共享同一截止预算}&quot;">​</a></h3><p>假设入口总预算2秒，服务A已花费0.4秒，下游B最多只能使用剩余1.6秒，还应为回传留余量。若A重新给B两秒，就可能让工作超过调用方等待期限。取消需要服务端及其后台任务配合检查；它不会撤销已完成的事务。具体语言如何传播上下文，按<a href="https://grpc.io/docs/guides/deadlines/" target="_blank" rel="noopener noreferrer">官方截止时间指南</a>核对。</p>',12)),t(r,{source:""}),a[1]||(a[1]=o("h3",{id:"part-1-消息数量决定调用形状",tabindex:"-1"},[s("消息数量决定调用形状 "),o("a",{class:"header-anchor",href:"#part-1-消息数量决定调用形状","aria-label":'Permalink to "消息数量决定调用形状 {#part-1-消息数量决定调用形状}"'},"​")],-1)),a[2]||(a[2]=o("p",null,"下面的“一”与“多”表示一次RPC内请求和响应消息的数量，不表示网络连接数。双向流的两条消息序列各自有序，但请求与响应的业务对应仍需协议字段说明。流结束后重新连接是否续传，必须另定义游标或业务确认。",-1)),t(r,{source:""}),a[3]||(a[3]=e('<h4 id="part-1-来源与适用边界" tabindex="-1">来源与适用边界 <a class="header-anchor" href="#part-1-来源与适用边界" aria-label="Permalink to &quot;来源与适用边界 {#part-1-来源与适用边界}&quot;">​</a></h4><ul><li><a href="https://grpc.io/docs/what-is-grpc/core-concepts/" target="_blank" rel="noopener noreferrer">英文官方、作者或规范原文</a>：本专题机制依据；按上述固定版本族阅读。</li><li><a href="https://learn.microsoft.com/zh-cn/aspnet/core/grpc/deadlines-cancellation?view=aspnetcore-10.0" target="_blank" rel="noopener noreferrer">中文官方或作者资料</a>：用于术语和讲解交叉核对，冲突以原始规范为准。</li><li><a href="https://grpc.io/docs/guides/deadlines/" target="_blank" rel="noopener noreferrer">截止时间</a>、<a href="https://grpc.io/docs/guides/cancellation/" target="_blank" rel="noopener noreferrer">取消</a>、<a href="https://pypi.org/project/grpcio-tools/1.76.0/" target="_blank" rel="noopener noreferrer">生成工具1.76.0</a>：源码仅静态复核，兼容与网络流程未执行。</li></ul><h2 id="part-2" tabindex="-1">gRPC状态码、安全重试与流控 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;gRPC状态码、安全重试与流控 {#part-2}&quot;">​</a></h2><p><span id="part-2-grpc调用契约-机制、交互与代价"></span></p><h3 id="part-2-status" tabindex="-1">状态码如何表达 <a class="header-anchor" href="#part-2-status" aria-label="Permalink to &quot;状态码如何表达 {#part-2-status}&quot;">​</a></h3><p>状态码如何表达业务失败要稳定区分：INVALID_ARGUMENT用于参数自身非法，NOT_FOUND用于资源不存在。UNAVAILABLE通常指暂时不可用，却不证明重试没有副作用；错误详情避免泄露内部异常堆栈，客户端按契约处理而非解析随意文本。</p><h3 id="part-2-retry" tabindex="-1">重试何时安全 <a class="header-anchor" href="#part-2-retry" aria-label="Permalink to &quot;重试何时安全 {#part-2-retry}&quot;">​</a></h3><p>重试何时安全取决于业务幂等与提交状态，不能看见网络错误就重复收费。只读查询通常更容易重试，有副作用方法需稳定请求标识、去重存储和结果查询。自动重试还受服务配置、状态码与总截止时间限制。</p><h3 id="part-2-flow" tabindex="-1">流控与应用缓冲 <a class="header-anchor" href="#part-2-flow" aria-label="Permalink to &quot;流控与应用缓冲 {#part-2-flow}&quot;">​</a></h3><p>流控与应用缓冲并非同一个队列。传输背压不能阻止应用无限积压待发消息；消费慢时应限制业务队列、取消无用工作并定义丢弃或拒绝规则。写入API返回也不等于对端已处理消息，必须根据语言实现核对阻塞语义。</p><h3 id="part-2-错误分类之后才决定重试" tabindex="-1">错误分类之后才决定重试 <a class="header-anchor" href="#part-2-错误分类之后才决定重试" aria-label="Permalink to &quot;错误分类之后才决定重试 {#part-2-错误分类之后才决定重试}&quot;">​</a></h3><p>参数非法应先修正输入，资源不存在应检查ID；只有契约允许重试且剩余期限足够时，才进入有限退避。对于写请求，还必须先确认幂等或查询原请求状态。把所有非OK都重试，会放大负载并掩盖调用错误。</p>',12)),t(r,{source:""}),a[4]||(a[4]=e('<h4 id="part-2-来源与适用边界" tabindex="-1">来源与适用边界 <a class="header-anchor" href="#part-2-来源与适用边界" aria-label="Permalink to &quot;来源与适用边界 {#part-2-来源与适用边界}&quot;">​</a></h4><ul><li><a href="https://grpc.io/docs/what-is-grpc/core-concepts/" target="_blank" rel="noopener noreferrer">英文官方、作者或规范原文</a>：本专题机制依据；按上述固定版本族阅读。</li><li><a href="https://learn.microsoft.com/zh-cn/aspnet/core/grpc/deadlines-cancellation?view=aspnetcore-10.0" target="_blank" rel="noopener noreferrer">中文官方或作者资料</a>：用于术语和讲解交叉核对，冲突以原始规范为准。</li><li><a href="https://grpc.io/docs/guides/deadlines/" target="_blank" rel="noopener noreferrer">截止时间</a>、<a href="https://grpc.io/docs/guides/cancellation/" target="_blank" rel="noopener noreferrer">取消</a>、<a href="https://pypi.org/project/grpcio-tools/1.76.0/" target="_blank" rel="noopener noreferrer">生成工具1.76.0</a>：源码仅静态复核，兼容与网络流程未执行。</li></ul><h2 id="part-3" tabindex="-1">gRPC身份认证与服务演进 <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;gRPC身份认证与服务演进 {#part-3}&quot;">​</a></h2><p><span id="part-3-grpc调用契约-反例、取舍与原文"></span></p><h3 id="part-3-security" tabindex="-1">通道与身份边界 <a class="header-anchor" href="#part-3-security" aria-label="Permalink to &quot;通道与身份边界 {#part-3-security}&quot;">​</a></h3><p>通道与身份边界分别处理传输保护与业务授权。TLS加密连接并验证配置的证书身份，但不自动判定某个用户能读某本书。元数据可携带令牌，服务端仍应核验；本机无TLS示例没有账号，不代表生产身份方案。</p><h3 id="part-3-evolution" tabindex="-1">服务升级如何兼容 <a class="header-anchor" href="#part-3-evolution" aria-label="Permalink to &quot;服务升级如何兼容 {#part-3-evolution}&quot;">​</a></h3><p>服务升级如何兼容同时检查方法名、消息字段号与应用语义。新增字段通常比改字段号安全，但改变“缺省值”的业务解释仍会破坏旧客户端。长连接滚动升级需考虑正在进行的流与优雅关闭，本课程没有部署演练。</p><h3 id="part-3-sources" tabindex="-1">gRPC规范与版本证据 <a class="header-anchor" href="#part-3-sources" aria-label="Permalink to &quot;gRPC规范与版本证据 {#part-3-sources}&quot;">​</a></h3><p>gRPC规范与版本证据采用官方核心概念、截止时间和取消指南，中文微软文档作交叉核对。生成器和运行库固定1.76.0教学族，protobuf固定6.33.0；这不是声称最新版本或已验证兼容，读者安装前应在隔离环境复核维护与安全状态。</p><h3 id="part-3-身份认证与资源授权逐层检查" tabindex="-1">身份认证与资源授权逐层检查 <a class="header-anchor" href="#part-3-身份认证与资源授权逐层检查" aria-label="Permalink to &quot;身份认证与资源授权逐层检查 {#part-3-身份认证与资源授权逐层检查}&quot;">​</a></h3><p>TLS解决连接保护和配置的对端身份，令牌认证确认当前调用主体，资源授权判断该主体能否访问目标书目。即使三层都通过，也仍需校验book_id等业务参数。滚动升级时同时运行新旧客户端，应分别检查消息兼容与默认语义，而不是只看握手成功。</p>',12)),t(r,{source:"Zmxvd2NoYXJ0IExSCkFbIuW7uueri+WPl+S/neaKpOmAmumBkyJdIC0tPiBCWyLmoLjpqozosIPnlKjouqvku70iXSAtLT4gQ1si5qCh6aqM6LWE5rqQ6K6/6Zeu5p2D6ZmQIl0gLS0+IERbIuaJp+ihjOWbvuS5puafpeivoiJdCkIgLS0+fCLouqvku73ml6DmlYgifCBFWyLorqTor4HlpLHotKUiXQpDIC0tPnwi5p2D6ZmQ5LiN6LazInwgRlsi5o6I5p2D5aSx6LSlIl0K"}),a[5]||(a[5]=e('<h4 id="part-3-来源与适用边界" tabindex="-1">来源与适用边界 <a class="header-anchor" href="#part-3-来源与适用边界" aria-label="Permalink to &quot;来源与适用边界 {#part-3-来源与适用边界}&quot;">​</a></h4><ul><li><a href="https://grpc.io/docs/what-is-grpc/core-concepts/" target="_blank" rel="noopener noreferrer">英文官方、作者或规范原文</a>：本专题机制依据；按上述固定版本族阅读。</li><li><a href="https://learn.microsoft.com/zh-cn/aspnet/core/grpc/deadlines-cancellation?view=aspnetcore-10.0" target="_blank" rel="noopener noreferrer">中文官方或作者资料</a>：用于术语和讲解交叉核对，冲突以原始规范为准。</li><li><a href="#part-1">本课程调用模型</a>：回顾远程调用与消息形状，和本页升级、安全边界对照。</li><li><a href="https://grpc.io/docs/guides/deadlines/" target="_blank" rel="noopener noreferrer">截止时间</a>、<a href="https://grpc.io/docs/guides/cancellation/" target="_blank" rel="noopener noreferrer">取消</a>、<a href="https://pypi.org/project/grpcio-tools/1.76.0/" target="_blank" rel="noopener noreferrer">生成工具1.76.0</a>：源码仅静态复核，兼容与网络流程未执行。</li></ul>',2))])}const b=p(c,[["render",h]]);export{I as __pageData,b as default};
